    @EventHandler( payloadType=CreateCertificationEvent.class )
    public void handle( CreateCertificationEvent event) {
	    LOGGER.info("handling CreateCertificationEvent - " + event );
	    Certification entity = new Certification();
            entity.setCertificationId( event.getCertificationId() );
            entity.setName( event.getName() );
            entity.setIssuer( event.getIssuer() );
            entity.setValidFrom( event.getValidFrom() );
            entity.setValidTo( event.getValidTo() );
            entity.setCredentialId( event.getCredentialId() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCertification( entity );
    }

    /*
     * @param	event UpdateCertificationEvent
     */
    @EventHandler( payloadType=UpdateCertificationEvent.class )
    public void handle( UpdateCertificationEvent event) {
    	LOGGER.info("handling UpdateCertificationEvent - " + event );
    	
	    Certification entity = new Certification();
            entity.setCertificationId( event.getCertificationId() );
            entity.setName( event.getName() );
            entity.setIssuer( event.getIssuer() );
            entity.setValidFrom( event.getValidFrom() );
            entity.setValidTo( event.getValidTo() );
            entity.setCredentialId( event.getCredentialId() );
            entity.setEmployee( event.getEmployee() );
            entity.setCourse( event.getCourse() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindCertification( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCertification( entity );        
    }
    
